actions:
  place_order:
    method: POST
    path: /plant_orders
    description: Place a new pending order. Price is plant price plus pot surcharge.
    input:
      customer_id:
        type: ref
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: customer
        onDelete: restrict
      plant_id:
        type: ref
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: plant
        onDelete: restrict
      pot_size:
        type: enum
        required: true
        nullable: false
        unique: false
        readonly: false
        values:
          - small
          - medium
          - large
      qty:
        type: int
        required: true
        nullable: false
        unique: false
        readonly: false
        min: 1
        max: 20
    handler: |-
      (ctx) => {
        const plant = ctx.db.get('plant', ctx.body.plant_id);
        if (plant === null) ctx.fail(404, 'not_found', 'plant ' + ctx.body.plant_id + ' not found');
        if (ctx.db.get('customer', ctx.body.customer_id) === null) ctx.fail(404, 'not_found', 'customer ' + ctx.body.customer_id + ' not found');
        if (plant.active !== true) ctx.fail(409, 'plant_inactive', 'plant ' + plant.id + ' is inactive and cannot be ordered');
        const surcharge = { small: 0, medium: 500, large: 1500 }[ctx.body.pot_size];
        const unit = plant.price_cents + surcharge;
        const n = ctx.db.list('plant_order').length;
        const order = ctx.db.create('plant_order', {
          order_code: 'PO-' + (1001 + n),
          customer_id: ctx.body.customer_id,
          plant_id: plant.id,
          pot_size: ctx.body.pot_size,
          qty: ctx.body.qty,
          unit_price_cents: unit,
          total_cents: unit * ctx.body.qty,
          status: 'pending',
          placed_at: ctx.now(),
          shipped_at: null,
          cancelled_at: null,
        });
        return { status: 201, body: order };
      }
  pay_order:
    method: POST
    path: /plant_orders/{id}/pay
    description: Confirm payment of a pending order and reserve stock.
    input: {}
    handler: |-
      (ctx) => {
        const o = ctx.db.get('plant_order', ctx.params.id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + ctx.params.id + ' not found');
        if (o.status !== 'pending') ctx.fail(409, 'invalid_state', 'order ' + o.id + ' is ' + o.status + '. Only pending orders can be paid.');
        const plant = ctx.db.get('plant', o.plant_id);
        if (plant.stock_qty < o.qty) ctx.fail(409, 'insufficient_stock', 'plant ' + plant.id + ' has ' + plant.stock_qty + ' in stock, order needs ' + o.qty);
        ctx.db.update('plant', plant.id, { stock_qty: plant.stock_qty - o.qty });
        const updated = ctx.db.update('plant_order', o.id, { status: 'paid' });
        return { status: 200, body: updated };
      }
  ship_order:
    method: POST
    path: /plant_orders/{id}/ship
    description: Ship a paid order.
    input: {}
    handler: |-
      (ctx) => {
        const o = ctx.db.get('plant_order', ctx.params.id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + ctx.params.id + ' not found');
        if (o.status !== 'paid') ctx.fail(409, 'invalid_state', 'order ' + o.id + ' is ' + o.status + '. Only paid orders can be shipped.');
        const updated = ctx.db.update('plant_order', o.id, { status: 'shipped', shipped_at: ctx.now() });
        return { status: 200, body: updated };
      }
  cancel_order:
    method: POST
    path: /plant_orders/{id}/cancel
    description: Cancel a pending or paid order. A paid order returns its stock.
    input: {}
    handler: |-
      (ctx) => {
        const o = ctx.db.get('plant_order', ctx.params.id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + ctx.params.id + ' not found');
        if (o.status !== 'pending' && o.status !== 'paid') ctx.fail(409, 'invalid_state', 'order ' + o.id + ' is ' + o.status + '. Only pending and paid orders can be cancelled.');
        if (o.status === 'paid') {
          const plant = ctx.db.get('plant', o.plant_id);
          ctx.db.update('plant', plant.id, { stock_qty: plant.stock_qty + o.qty });
        }
        const updated = ctx.db.update('plant_order', o.id, { status: 'cancelled', cancelled_at: ctx.now() });
        return { status: 200, body: updated };
      }
jobs:
  auto_cancel_stale_pending:
    description: Daily. Cancels pending orders placed 5 or more days ago. Stock is untouched.
    every: 1d
    run: |-
      (ctx) => {
        const now = ctx.now();
        for (const o of ctx.db.list('plant_order', { where: { status: 'pending' } })) {
          if (ctx.time.minutesBetween(o.placed_at, now) >= 5 * 24 * 60) {
            ctx.db.update('plant_order', o.id, { status: 'cancelled', cancelled_at: now });
          }
        }
      }
