tests:
  place_order_prices_and_validates:
    description: Creates a customer and a plant, places a large pot order of qty 2 and checks status pending, unit price 3500, total 7000, placed_at and an order_code. Then qty 0 answers 400 input.invalid.
    script: |-
      (ctx) => {
        const c = ctx.api('POST', '/customers', { name: 'Acc Tester One', email: 'acc.one@plantdesk.test' });
        ctx.assert(c.status === 201, 'create customer returned ' + c.status + ' ' + JSON.stringify(c.body));
        const p = ctx.api('POST', '/plants', { name: 'Acc Calathea Orbifolia One', price_cents: 2000, stock_qty: 10, active: true });
        ctx.assert(p.status === 201, 'create plant returned ' + p.status + ' ' + JSON.stringify(p.body));
        const at = ctx.now();
        const o = ctx.api('POST', '/plant_orders', { customer_id: c.body.id, plant_id: p.body.id, pot_size: 'large', qty: 2 });
        ctx.assert(o.status === 201, 'place_order returned ' + o.status + ' ' + JSON.stringify(o.body));
        ctx.assert(o.body.status === 'pending', 'new order is pending, got ' + o.body.status);
        ctx.assert(o.body.unit_price_cents === 3500, 'unit price 2000 + 1500 large surcharge = 3500, got ' + o.body.unit_price_cents);
        ctx.assert(o.body.total_cents === 7000, 'total 7000, got ' + o.body.total_cents);
        ctx.assert(o.body.placed_at === at, 'placed_at is the call time ' + at + ', got ' + o.body.placed_at);
        ctx.assert(typeof o.body.order_code === 'string' && /^PO-\d+$/.test(o.body.order_code), 'order_code looks like PO-1234, got ' + o.body.order_code);
        ctx.assert(o.body.shipped_at === null && o.body.cancelled_at === null, 'no shipped_at or cancelled_at yet');
        const small = ctx.api('POST', '/plant_orders', { customer_id: c.body.id, plant_id: p.body.id, pot_size: 'small', qty: 1 });
        ctx.assert(small.status === 201 && small.body.unit_price_cents === 2000, 'small pot has no surcharge: ' + JSON.stringify(small.body));
        const zero = ctx.api('POST', '/plant_orders', { customer_id: c.body.id, plant_id: p.body.id, pot_size: 'small', qty: 0 });
        ctx.assert(zero.status === 400 && zero.body.error.code === 'input.invalid', 'qty 0: ' + JSON.stringify(zero));
      }
  pay_reserves_stock:
    description: Stock 2, order qty 3. Paying answers 409 insufficient_stock and changes nothing. After a restock to 3, paying works and leaves stock 0. Paying twice answers 409 invalid_state.
    script: |-
      (ctx) => {
        const c = ctx.api('POST', '/customers', { name: 'Acc Tester Two', email: 'acc.two@plantdesk.test' }).body;
        const p = ctx.api('POST', '/plants', { name: 'Acc Fiddle Leaf Fig Two', price_cents: 4500, stock_qty: 2, active: true }).body;
        ctx.assert(c.id && p.id, 'setup rows created');
        const o = ctx.api('POST', '/plant_orders', { customer_id: c.id, plant_id: p.id, pot_size: 'medium', qty: 3 }).body;
        ctx.assert(o.id && o.status === 'pending', 'order placed pending: ' + JSON.stringify(o));
        const short = ctx.api('POST', '/plant_orders/' + o.id + '/pay', {});
        ctx.assert(short.status === 409 && short.body.error.code === 'insufficient_stock', 'pay with too little stock: ' + JSON.stringify(short));
        ctx.assert(ctx.api('GET', '/plant_orders/' + o.id).body.status === 'pending', 'order is still pending after the refused pay');
        ctx.assert(ctx.api('GET', '/plants/' + p.id).body.stock_qty === 2, 'stock is still 2 after the refused pay');
        const restock = ctx.api('PATCH', '/plants/' + p.id, { stock_qty: 3 });
        ctx.assert(restock.status === 200 && restock.body.stock_qty === 3, 'restock: ' + JSON.stringify(restock));
        const paid = ctx.api('POST', '/plant_orders/' + o.id + '/pay', {});
        ctx.assert(paid.status === 200 && paid.body.status === 'paid', 'pay: ' + JSON.stringify(paid));
        ctx.assert(ctx.api('GET', '/plants/' + p.id).body.stock_qty === 0, 'stock is 0 after paying qty 3');
        const again = ctx.api('POST', '/plant_orders/' + o.id + '/pay', {});
        ctx.assert(again.status === 409 && again.body.error.code === 'invalid_state', 'second pay: ' + JSON.stringify(again));
        ctx.assert(ctx.api('GET', '/plants/' + p.id).body.stock_qty === 0, 'the refused second pay left stock at 0');
      }
  ship_only_paid_orders:
    description: Shipping a pending order answers 409 invalid_state. After paying, shipping sets shipped_at to the call time. Shipping, paying or cancelling a shipped order answers 409 invalid_state.
    script: |-
      (ctx) => {
        const c = ctx.api('POST', '/customers', { name: 'Acc Tester Three', email: 'acc.three@plantdesk.test' }).body;
